    if (conf[idx] != -1) return conf[idx];
    if (a[idx].size() == 0) return conf[idx] = 0;
    if (a[idx].size() == 1) return conf[idx] = (1 << (a[idx][0] - 1));
    else return conf[idx] = (1 << (a[idx][0] - 1)) | (1 << (a[idx][1] - 1));
}

