void solve() {
    cin >> n >> k;
    for (int i = 0; i < n; i++) {
        cin >> a[i] >> b[i];
    }

    int max_sum = -1;
    int best_permutation[MAX_N];
    int best_seq[MAX_N * 2];

    do {
        int sum = 0;
        int seq[MAX_N * 2];
        int seq_len = 0;
        for (int i = 0; i < k; i++) {
            sum += a[i];
            seq[seq_len++] = i + 1;
