            sum += a[i] + (k - 1) * b[i];
            seq[seq_len++] = i + 1;
            seq[seq_len++] = -(i + 1);
        }
        if (sum > max_sum) {
            max_sum = sum;
            for (int i = 0; i < n; i++) {
                best_permutation[i] = i;
            }
            for (int i = 0; i < seq_len; i++) {
                best_seq[i] = seq[i];
            }
        }
