bool isZigzag(long long num) {
    std::string str = std::to_string(num);
    if (str.length() == 1) return true;

    bool increase = str[0] < str[1];
    for (int i = 1; i < str.length() - 1; i++) {
        if (increase && str[i] < str[i + 1]) return false;
        if (!increase && str[i] > str[i + 1]) return false;
        increase = !increase;
    }
    return true;
}

