struct Vector {
    int x, y;
};

bool check(const Vector& A, const Vector& B, const Vector& C) {
    if (C.x == 0 && C.y == 0) {
        return (A.x == B.x && A.y == B.y);
    }

    int dx = B.x - A.x;
    int dy = B.y - A.y;

    int d = C.x * C.x + C.y * C.y;
    int a = C.x * dx + C.y * dy;

    if (a % d != 0) {
        return false;
    }

    int k = a / d;

    int xx = dx - k * C.x;
    int yy = dy - k * C.y;

    return (xx == 0 && yy == 0) || (abs(xx) == abs(C.y) && abs(yy) == abs(C.x));
}

int main() {
