    cin >> A.x >> A.y;
    cin >> B.x >> B.y;
    cin >> C.x >> C.y;

    if (check(A, B, C)) {
        cout << "YES" << endl;
    } else {
        vector<Vector> V = {{A.y, -A.x}, {-A.x, -A.y}, {-A.y, A.x}};
        for (int i = 0; i < 3; ++i) {
            if (check(V[i], B, C)) {
                cout << "YES" << endl;
                return 0;
            }
        }
        cout << "NO" << endl;
    }

    return 0;
}

