struct Edge {
    int v, w, id;
    bool operator<(const Edge& e) const {
        return w > e.w;
    }
};

void dijkstra(int s, vector<int>& dist) {
    priority_queue<Edge> pq;
    pq.push({s, 0, -1});
    dist[s] = 0;

    while (!pq.empty()) {
        int u = pq.top().v;
        int w = pq.top().w;
        pq.pop();

        for (auto& e : edges[u]) {
            int v = e.first;
            int edge_w = e.second;

            if (w + edge_w < dist[v]) {
                dist[v] = w + edge_w;
                pq.push({v, dist[v], -1});
            }
        }
    }
}

