    cin.tie(NULL);

    cin >> n >> m >> k >> q;

    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        u--, v--;
        edges[u].emplace_back(v, w);
        edges[v].emplace_back(u, w);
    }

    vector<vector<int>> dist(k, vector<int>(n, INF));
    for (int i = 0; i < k; i++) {
        dijkstra(i, dist[i]);
    }

    for (int i = 0; i < q; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;

        int l = 0, r = 1e9 + 1;
        while (l < r) {
            int mid = (l + r) / 2;
            bool ok = false;

            vector<int> d(n, INF);
            d[u] = mid;
            priority_queue<Edge> pq;
            pq.push({u, 0, -1});

            while (!pq.empty()) {
                int u1 = pq.top().v;
                int w = pq.top().w;
                pq.pop();

                for (auto& e : edges[u1]) {
                    int v1 = e.first;
                    int edge_w = e.second;

                    if (w + edge_w <= mid) {
                        if (dist[v][v1] < d[v1]) {
                            d[v1] = dist[v][v1];
                            pq.push({v1, dist[v][v1], -1});
                        } else if (d[u1] + edge_w < d[v1]) {
                            d[v1] = d[u1] + edge_w;
                            pq.push({v1, d[v1], -1});
                        }
                    }
                }
            }

            for (int j = 0; j < k; j++) {
                if (d[j] <= mid) {
                    ok = true;
                    break;
                }
            }

            if (ok) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }

        ans[i] = l;
    }

    for (int i = 0; i < q; i++) {
