    } else if (equal(dist(cx, cy, x, y) * dist(cx, cy, x, y), ca * ca + (dist(x, y, ax, ay) * dist(x, y, ax, ay)))) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }

