    }

    for (int i = 0; i < N - 1; i++) {
        G[i][i + 1] = G[i + 1][i] = 1;
    }

    vector<int> perm(M);
    iota(perm.begin(), perm.end(), 0);

    int ans = 0;
    do {
        vector<int> used(M);
        bool ok = true;
        for (int i = 0; i < M; i++) {
            int v = A[perm[i]];
            int u = B[perm[i]];
            if (G[v][u] == 0) {
                ok = false;
                break;
            }

            used[i] = 1;
            G[v][u] = G[u][v] = 0;
        }

        if (ok) {
            vector<int> sum(N);
