                    group[find(u)] += group[find(v)];
                    group[find(v)] = 0;
                    P[find(v)] = find(u);
                }
            }

            for (int i = 0; i < N; i++) {
                cnt += sum[i] - 1;
            }

            ans = (ans + (1LL * cnt * (cnt - 1) / 2) % MOD * N) % MOD;
            for (int i = 0; i < N; i++) {
                if (group[i] > 0) {
