bool isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

struct Date {
    int year, month, day;
    Date() {}
    Date(int y, int m, int d) : year(y), month(m), day(d) {}
};

bool operator<(const Date& a, const Date& b) {
    if (a.year != b.year) return a.year < b.year;
    if (a.month != b.month) return a.month < b.month;
    return a.day < b.day;
}

int daysInMonth(int month, int year) {
    if (month == 2) {
        return isLeapYear(year) ? 29 : 28;
    } else if (month == 4 || month == 6 || month == 9 || month == 11) {
        return 30;
    } else {
        return 31;
    }
}

Date nextBirthday(const Date& date) {
    int year = date.year, month = date.month;
    if (month == 2 && date.day == 29 && !isLeapYear(date.year + 1)) {
        month = 3;
        year++;
    } else {
        if (date.day < daysInMonth(date.month, date.year)) {
            return Date(date.year, date.month, date.day + 1);
        } else if (date.month < 12) {
            return Date(date.year, date.month + 1, 1);
        } else {
            return Date(date.year + 1, 1, 1);
        }
    }
    return Date(year, month, 1);
}

int age(const Date& birthDate, const Date& currentDate) {
    int years = currentDate.year - birthDate.year;
    if (currentDate < Date(birthDate.year + years, birthDate.month, birthDate.day)) {
        years--;
    }
    return years;
}

int main() {
    int y1, m1, d1, y2, m2, d2;
    std::cin >> y1 >> m1 >> d1 >> y2 >> m2 >> d2;

    Date hatsumi(y1, m1, d1);
    Date taku(y2, m2, d2);

    int maxDiff = std::abs(age(hatsumi, taku));

    while (hatsumi.year < 3000 || taku.year < 3000) {
        Date newHatsumi = nextBirthday(hatsumi);
        Date newTaku = nextBirthday(taku);
        if (newHatsumi < newTaku) {
            hatsumi = newHatsumi;
        } else if (newHatsumi > newTaku) {
            taku = newTaku;
        } else {
            hatsumi = newHatsumi;
            taku = newTaku;
        }
        maxDiff = std::max(maxDiff, std::abs(age(hatsumi, taku)));
    }

    std::cout << maxDiff << std::endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <climits>

using namespace std;

const int MAX_N = 100005;
const long long INF = LLONG_MAX;

vector<pair<int, int>> graph[MAX_N];
long long dist[MAX_N];

void dijkstra(int start) {
    for (int i = 1; i <= MAX_N; i++) {
        dist[i] = INF;
    }
    dist[start] = 0;

    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        long long d = pq.top().first;
        int u = pq.top().second;
        pq.pop();

        if (d > dist[u]) {
            continue;
        }

        for (auto& edge : graph[u]) {
            int v = edge.first;
            long long w = edge.second;

            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
}

int main() {
    int N, M;
    cin >> N >> M;

    int S, T;
    cin >> S >> T;

    int U, V;
    cin >> U >> V;

    for (int i = 0; i < M; i++) {
        int A, B, C;
        cin >> A >> B >> C;

        graph[A].emplace_back(B, C);
        graph[B].emplace_back(A, C);
    }

    dijkstra(S);
    vector<int> path;
    int current = T;
    while (current != S) {
        path.push_back(current);
        for (auto& edge : graph[current]) {
            if (dist[current] - edge.second == dist[edge.first]) {
                current = edge.first;
                break;
            }
        }
    }
    path.push_back(S);
    reverse(path.begin(), path.end());

    vector<bool> used(M + 1, false);
    for (int i = 0; i < path.size() - 1; i++) {
        for (auto& edge : graph[path[i]]) {
            if (edge.first == path[i + 1]) {
                for (int j = 0; j < M; j++) {
                    int A, B, C;
                    cin >> A >> B >> C;
                    if (A == path[i] && B == path[i + 1] || A == path[i + 1] && B == path[i]) {
                        used[j + 1] = true;
                    }
                }
            }
        }
    }

    for (int i = 1; i <= N; i++) {
        graph[i].clear();
    }

    for (int i = 0; i < M; i++) {
        int A, B, C;
        cin >> A >> B >> C;
        if (used[i + 1]) {
            graph[A].emplace_back(B, 0);
            graph[B].emplace_back(A, 0);
        } else {
            graph[A].emplace_back(B, C);
            graph[B].emplace_back(A, C);
        }
    }

    dijkstra(U);

    cout << dist[V] << endl;

    return 0;
}

