            for (int j = 0; j < w; ++j) {
                cin >> grid[i][j];
            }
        }

        memset(visited, false, sizeof(visited));
        memset(distance, 0x3f, sizeof(distance));

        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if (islower(grid[i][j])) {
                    int mask = 0;
                    for (int k = 0; k < n; ++k) {
                        if (grid[i][j] == 'a' + k) {
                            mask |= (1 << k);
                            grid[k][0] = 'a' + k;
                            grid[k][1] = i;
                        }
                    }

                    bfs(mask, i, j);
                }
            }
        }

        int ans = 1e9;

        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if (isupper(grid[i][j])) {
                    int mask = 0;
                    for (int k = 0; k < n; ++k) {
                        if (grid[i][j] == 'A' + k) {
                            mask |= (1 << k);
                            grid[k][2] = 'A' + k;
                            grid[k][3] = i;
                        }
                    }

                    ans = min(ans, distance[mask][i][j]);
                }
            }
        }

        cout << ans << "\n";
    }

    return 0;
}

