const int MODE = 1e9 + 7;
const int MAXN = 1e3 + 5;

int f[MAXN][MAXN], r, c, a1, a2, b1, b2;

void update(int& x, int y) {
    x += y;
    if (x >= MODE) {
        x -= MODE;
    }
}

