    int sign = 0;

    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        int k = (j + 1) % n;

        double cp = crossProduct(points[i], points[j], points[k]);

        if (sign == 0) {
            sign = (cp > 0) ? 1 : -1;
        } else if ((cp > 0 && sign < 0) || (cp < 0 && sign > 0)) {
            isConvex = false;
            break;
        }
    }

    cout << (isConvex ? "1" : "0") << endl;

    return 0;
}

