void solve() {
    cin >> n >> m;
    for (int i = 1; i <= m; i++) {
        int ai, bi;
        cin >> ai >> bi;
        a[ai].push_back(bi);
        b[bi].push_back(ai);
    }

    for (int i = 1; i <= n; i++) {
        sort(a[i].begin(), a[i].end());
        sort(b[i].begin(), b[i].end());
    }

    for (int i = 1; i <= n; i++) {
        ll ans = 0;
        vector<int> dst;
        for (int j = 1; j <= m; j++) {
