void dfs(int v, int p = -1) {
    sz[v] = 1;
    for (int to : g[v]) {
        if (to != p) {
            dfs(to, v);
            sz[v] += sz[to];
        }
    }
}

bool check(int v, int p = -1) {
    int mx = 0;
    for (int to : g[v]) {
        if (to != p) {
            mx = max(mx, sz[to]);
        }
    }
    return mx <= n / 2;
}

bool check2(int v, int p = -1) {
    int cnt = 0;
    for (int to : g[v]) {
        if (to != p) {
            cnt += (sz[to] > n / 2);
        }
    }
    return cnt <= 1;
}

vector<int> get(int v, int p = -1) {
    vector<int> res;
    res.push_back(v);
    for (int to : g[v]) {
        if (to != p) {
            res.push_back(sz[to]);
        }
    }
    sort(res.begin(), res.end(), [](int x, int y) { return sz[x] > sz[y]; });
    return res;
}

bool check3(int v, int p = -1) {
    vector<int> c1 = get(v, p);
    vector<int> c2;
    for (int to : g[v]) {
        if (to != p) {
            c2 = get(to, v);
            if (c2.size() > 1 && c2[1] > n / 2) return false;
        }
    }
    for (int to : g[v]) {
        if (to != p) {
            int tmp = sz[v] - sz[to];
            if (tmp > n / 2) return false;
        }
    }
    if (c1.size() > 1 && (c1[0] + c1[1]) > n) return false;
    return true;
}

bool check4(int v, int p = -1) {
    for (int to : g[v]) {
        if (to != p) {
            int tmp = sz[v] - sz[to];
            if (tmp > n / 2) {
                int tmp2 = sz[to];
                if (tmp2 > n / 2) return false;
            }
        }
    }
    vector<int> c1 = get(v, p);
    if (c1.size() > 1 && c1[0] + c1[1] > n) return false;
    return true;
}

