                    if (i <= s.second && i + j >= s.first) {
                        available = false;
                        break;
                    }
                }
                if (!available) {
                    break;
                }
            }
            if (available) {
                start = i;
                found = true;
                break;
            }
        }

        scheduled.push_back({start, start + r.second - 1});
        cout << start << " " << (start + r.second - 1) << "\n";
    }

    return 0;
}

