int counter, edgeCount;
std::vector<std::pair<int, int>> edges;

void dfs(int u) {
    low[u] = num[u] = counter++;
    for (auto &e : adj[u]) {
        int v = e.first;
        if (num[v] == -1) {
            parent[v] = u;
            dfs(v);
            low[u] = std::min(low[u], low[v]);
        } else if (v != parent[u]) {
            low[u] = std::min(low[u], num[v]);
        }
    }
}

