std::unordered_map<int, std::vector<int>> mp;

void dfs(int x, int m, std::vector<int>& path) {
    if (mp.find(m) != mp.end()) {
        for (auto y : mp[m]) {
            path.push_back(y);
        }
        return;
    }

    if (m == 1) {
        mp[m].push_back(x);
        path.push_back(x);
        return;
    }

    dfs(a[x], m - 1, path);
    mp[m].push_back(x);
    path.push_back(x);
}

